#### REQ-LENS-006-006: Custom Dashboard Templates

**Status**: Mandatory
**Rationale**: Standardized views for operations and development teams

**Required Dashboards**:
1. **Platform Operations Dashboard**:
   - Cluster health summary (brokers, topics, consumer groups)
   - Critical alerts widget
   - Top 10 topics by throughput
   - Consumer lag SLA compliance (%)
   - Broker resource utilization heat map

2. **Developer Dashboard** (per business unit/application):
   - Topics owned by application
   - Consumer group lag for application consumers
   - Producer throughput and error rates
   - Schema registry usage (if applicable)
   - Recent topology changes

3. **Capacity Planning Dashboard**:
   - Topic growth trends (7-day, 30-day projections)
   - Broker disk utilization forecast
   - Consumer group scaling recommendations
   - Network bandwidth utilization

**Implementation**:

**1. Platform Operations Dashboard** (JSON):
```json
{
  "id": "platform-operations-dashboard",
  "title": "Platform Operations - Cluster Health Summary",
  "description": "Executive dashboard for Platform Engineering team with cluster-wide health indicators",
  "layout": "grid",
  "widgets": [
    {
      "type": "stat",
      "title": "Cluster Health Score",
      "position": {"x": 0, "y": 0, "w": 3, "h": 2},
      "query": "SELECT (100 - (SUM(offline_partitions) + SUM(under_replicated_partitions)) * 10) AS health_score FROM lenses.cluster_metrics",
      "visualization": {
        "type": "gauge",
        "threshold": {"green": ">= 95", "yellow": ">= 80", "red": "< 80"},
        "unit": "score"
      }
    },
    {
      "type": "stat",
      "title": "Brokers Online",
      "position": {"x": 3, "y": 0, "w": 2, "h": 2},
      "query": "SELECT COUNT(*) as online, (SELECT COUNT(*) FROM lenses.brokers) as total FROM lenses.brokers WHERE status='ONLINE'",
      "visualization": {
        "type": "fraction",
        "format": "{online} / {total}"
      }
    },
    {
      "type": "stat",
      "title": "Total Topics",
      "position": {"x": 5, "y": 0, "w": 2, "h": 2},
      "query": "SELECT COUNT(DISTINCT topic_name) FROM lenses.topic_metrics_realtime"
    },
    {
      "type": "stat",
      "title": "Consumer Groups",
      "position": {"x": 7, "y": 0, "w": 2, "h": 2},
      "query": "SELECT COUNT(DISTINCT group_id) FROM lenses.consumer_group_lag_sla"
    },
    {
      "type": "alerts",
      "title": "Critical Alerts (Last 24h)",
      "position": {"x": 9, "y": 0, "w": 3, "h": 2},
      "query": "SELECT alert_name, severity, timestamp, message FROM lenses.alerts WHERE severity IN ('critical', 'high') AND timestamp >= NOW() - INTERVAL '24 hours' ORDER BY timestamp DESC LIMIT 10"
    },
    {
      "type": "table",
      "title": "Top 10 Topics by Throughput",
      "position": {"x": 0, "y": 2, "w": 6, "h": 4},
      "query": "SELECT topic_name, messages_in_rate, bytes_in_rate, partition_count, under_replicated_count FROM lenses.topic_metrics_realtime ORDER BY bytes_in_rate DESC LIMIT 10"
    },
    {
      "type": "stat",
      "title": "Consumer Lag SLA Compliance",
      "position": {"x": 6, "y": 2, "w": 3, "h": 2},
      "query": "SELECT (COUNT(CASE WHEN sla_status='COMPLIANT' THEN 1 END) * 100.0 / COUNT(*)) FROM lenses.consumer_group_lag_sla",
      "visualization": {
        "type": "gauge",
        "unit": "percent",
        "threshold": {"green": ">= 95", "yellow": ">= 90", "red": "< 90"},
        "target": 95
      }
    },
    {
      "type": "heatmap",
      "title": "Broker Resource Utilization Heat Map",
      "position": {"x": 9, "y": 2, "w": 3, "h": 4},
      "query": "SELECT broker_id, 'CPU' as metric, cpu_percent as value FROM lenses.broker_metrics UNION ALL SELECT broker_id, 'Memory', memory_percent FROM lenses.broker_metrics UNION ALL SELECT broker_id, 'Disk', disk_percent FROM lenses.broker_metrics",
      "visualization": {
        "type": "heatmap",
        "colorScale": {"low": "green", "medium": "yellow", "high": "red"}
      }
    },
    {
      "type": "timeseries",
      "title": "Cluster Throughput (Last 7 Days)",
      "position": {"x": 0, "y": 6, "w": 12, "h": 3},
      "query": "SELECT timestamp, SUM(bytes_in_rate) as total_throughput FROM lenses.topic_metrics_history WHERE timestamp >= NOW() - INTERVAL '7 days' GROUP BY timestamp",
      "visualization": {
        "type": "area",
        "yAxis": {"label": "MB/sec", "format": "bytes"}
      }
    }
  ],
  "refresh_interval": "30s",
  "access_control": {
    "groups": ["platform-admins", "platform-engineering", "sre-team"]
  }
}
```

**2. Developer Dashboard Template** (Per Business Unit):
```json
{
  "id": "developer-dashboard-template",
  "title": "Developer Dashboard - {BUSINESS_UNIT}",
  "description": "Business unit-specific metrics for application developers",
  "filters": {
    "topic_prefix": "{BUSINESS_UNIT}.*",
    "consumer_group_prefix": "{BUSINESS_UNIT}-*"
  },
  "widgets": [
    {
      "type": "table",
      "title": "My Topics",
      "query": "SELECT topic_name, messages_in_rate, bytes_in_rate, partition_count FROM lenses.topic_metrics_realtime WHERE topic_name LIKE '{BUSINESS_UNIT}.%' ORDER BY bytes_in_rate DESC"
    },
    {
      "type": "table",
      "title": "My Consumer Groups - Lag Status",
      "query": "SELECT group_id, topic_name, SUM(lag_messages) AS total_lag, MAX(sla_status) AS sla FROM lenses.consumer_group_lag_sla WHERE group_id LIKE '{BUSINESS_UNIT}-%' GROUP BY group_id, topic_name ORDER BY total_lag DESC"
    },
    {
      "type": "timeseries",
      "title": "Producer Throughput",
      "query": "SELECT client_id, timestamp, record_send_rate FROM lenses.producer_metrics_history WHERE client_id LIKE '%{BUSINESS_UNIT}%' AND timestamp >= NOW() - INTERVAL '24 hours'"
    },
    {
      "type": "stat",
      "title": "Consumer Lag SLA Compliance",
      "query": "SELECT (COUNT(CASE WHEN sla_status='COMPLIANT' THEN 1 END) * 100.0 / COUNT(*)) FROM lenses.consumer_group_lag_sla WHERE group_id LIKE '{BUSINESS_UNIT}-%'",
      "visualization": {"type": "gauge", "threshold": {"green": ">= 95", "yellow": ">= 90", "red": "< 90"}}
    },
    {
      "type": "table",
      "title": "Recent Topology Changes",
      "query": "SELECT timestamp, event_type, topic_name, details FROM lenses.topology_changes WHERE topic_name LIKE '{BUSINESS_UNIT}.%' AND timestamp >= NOW() - INTERVAL '7 days' ORDER BY timestamp DESC LIMIT 20"
    }
  ],
  "refresh_interval": "1m",
  "access_control": {
    "groups": ["{BUSINESS_UNIT}-developers", "{BUSINESS_UNIT}-leads"]
  }
}
```

**3. Capacity Planning Dashboard**:
```json
{
  "id": "capacity-planning-dashboard",
  "title": "Capacity Planning - Growth & Forecasting",
  "description": "Topic growth trends, disk utilization forecasts, and scaling recommendations",
  "widgets": [
    {
      "type": "timeseries",
      "title": "Topic Growth Trends (30-Day Projection)",
      "query": "SELECT topic_name, date, total_messages, projected_30day FROM lenses.topic_growth_forecast WHERE topic_name IN (SELECT topic_name FROM lenses.topic_metrics_realtime ORDER BY total_message_count DESC LIMIT 10)",
      "visualization": {
        "type": "line",
        "groupBy": "topic_name",
        "series": [
          {"field": "total_messages", "label": "Actual", "style": "solid"},
          {"field": "projected_30day", "label": "30-day Forecast", "style": "dashed"}
        ]
      }
    },
    {
      "type": "table",
      "title": "Broker Disk Utilization Forecast",
      "query": "SELECT broker_id, current_disk_percent, projected_disk_percent_7day, projected_disk_percent_30day, days_until_80_percent FROM lenses.broker_capacity_forecast ORDER BY days_until_80_percent ASC",
      "visualization": {
        "type": "table",
        "alert": {
          "days_until_80_percent": {"red": "< 30", "yellow": "< 60"}
        }
      }
    },
    {
      "type": "table",
      "title": "Consumer Group Scaling Recommendations",
      "query": "SELECT consumer_group, current_member_count, recommended_member_count, reason FROM lenses.consumer_scaling_recommendations ORDER BY priority DESC"
    },
    {
      "type": "timeseries",
      "title": "Network Bandwidth Utilization Trend",
      "query": "SELECT timestamp, SUM(network_in_mbps) as total_in, SUM(network_out_mbps) as total_out FROM lenses.broker_metrics_history WHERE timestamp >= NOW() - INTERVAL '30 days' GROUP BY timestamp",
      "visualization": {
        "type": "area",
        "yAxis": {"label": "Mbps"}
      }
    }
  ],
  "refresh_interval": "1h",
  "access_control": {
    "groups": ["platform-admins", "capacity-planning-team"]
  }
}
```
